def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    if not h:
        return out
    # Bottom-row 5s are the ray sources. Each ray travels upward;
    # any colored cell encountered along its column changes the ray color.
    for c, source in enumerate(grid[-1]):
        if source != 5:
            continue
        color = source
        for r in range(h - 2, -1, -1):
            if grid[r][c] != 0:
                color = grid[r][c]
            else:
                out[r][c] = color
    return out
